#!/usr/bin/env python3
"""As 8 aulas do Kit Completo. Uso: python3 build_aulas.py [nome...]"""
import sys, video_engine as V
T=lambda img,foco,fala,leg: {'tipo':'tela','img':img,'foco':foco,'fala':fala,'legenda':leg}
C=lambda tit,txt,fala,leg,box=None: {'tipo':'card','titulo':tit,'texto':txt,'fala':fala,'legenda':leg,'box':box}
L=lambda tit,itens,fala,leg: {'tipo':'lista','titulo':tit,'itens':itens,'fala':fala,'legenda':leg}
R={
'aula-01-pensar-antes-de-abrir-o-excel':{'n':1,'titulo':'Pensar antes de abrir o Excel','sub':'o que a planilha precisa responder','cenas':[
 {'tipo':'capa','fala':'Aula um. Pensar antes de abrir o Excel. Esta aula tem dois minutos e é a mais importante do kit: ela evita a tarde perdida arrumando coluna.'},
 C('A planilha não é o objetivo','A planilha existe para responder uma pergunta de alguém, em algum momento, para tomar uma decisão. Se você não sabe qual é a pergunta, qualquer coluna parece necessária, e a planilha cresce até ninguém usar.','Quase todo mundo abre o Excel primeiro e pensa depois. Aí a planilha vira um monstro de vinte colunas que ninguém preenche. A regra do método é simples: a planilha responde uma pergunta. Se você não sabe a pergunta, ainda não é hora de abrir o arquivo.','Primeiro a pergunta, depois o arquivo'),
 L('As três perguntas antes de qualquer planilha',['Quem lê? Eu, meu chefe, meu cliente, minha equipe.','Com que frequência? Todo dia, toda sexta, no dia 30.','Para decidir o quê? Cobrar, cortar, contratar, aprovar.'],'São três perguntas. Quem lê. Com que frequência. Para decidir o quê. Um controle de propostas, por exemplo: quem lê sou eu, toda sexta, para decidir quais propostas cobrar. Pronto: a planilha precisa mostrar as propostas abertas, ordenadas por tempo parado. Todo o resto é enfeite.','Quem lê, quando, para decidir o quê'),
 C('Prompt Estruturar 01','Descreva a necessidade em três a cinco frases. A IA devolve uma tabela: pergunta que a planilha responde, quem lê, dado de entrada, de onde vem, saída. E diz o que não deve entrar.','Na Biblioteca B, o prompt Estruturar zero um faz esse exercício com você em cinco minutos. Você descreve a necessidade em poucas frases e a IA devolve a tabela com a pergunta, quem lê, o dado de entrada e a saída. O mais útil é a última parte: o que não deve entrar.','Cinco minutos com a IA antes de abrir o arquivo',box='Necessidade: quero controlar as propostas que envio, saber quanto tenho em aberto e quanto devo fechar no mês. Eu leio toda sexta; meu sócio, no fim do mês.'),
 C('Entrada, saída, quem lê','A frase que resume qualquer planilha boa: "Você preenche X; a planilha mostra Y para Z, quando W." Se a frase não fecha, a planilha não está pronta para existir.','Depois do prompt, teste a frase: você preenche isso; a planilha mostra aquilo, para fulano, toda sexta. Se a frase não fecha, falta decidir alguma coisa. O prompt Estruturar zero dois escreve essa frase e sugere o nome do arquivo.','A frase que resume a planilha'),
 T('docs/tela-base-base.png',[0,0,0.7,0.58],'Toda planilha do kit segue a mesma anatomia. Uma aba de lançamento, como esta, a Base: uma linha por registro, uma coluna por informação, cabeçalho na linha um, nada mesclado, nada de total no meio. É a estrutura que a tabela dinâmica lê e que a IA entende.','Uma linha por registro, uma coluna por informação'),
 L('As sete regras de uma base limpa',['Cabeçalho na linha 1, uma coluna por informação','Uma linha por registro; sem linhas em branco ou subtotais no meio','Data é data, número é número, texto é texto','Categorias vêm de lista, não da digitação','Nada mesclado','O que é calculado fica em coluna própria, com a mesma fórmula do topo ao fim','Totais e análises ficam em outra aba'],'As sete regras da base limpa estão na aba Como usar da planilha dez. Vale ler duas vezes. A mais quebrada é a quatro: categoria digitada à mão. Marketing com M maiúsculo, marketing com m minúsculo e M K T viram três coisas diferentes, e o painel erra. Lista resolve.','As sete regras'),
 T('docs/tela-base-checklist.png',[0,0,0.7551,1],'A planilha Base Limpa tem um checklist que conta o que está errado: linhas sem valor, datas fora do intervalo, categorias fora da lista, status em branco, duplicadas. Tudo zerado, a base está pronta para análise.','O checklist diz se a base está pronta'),
 C('Usar a planilha do kit ou montar a sua?','Se a pergunta cabe em uma das dez planilhas do kit, use a planilha. Se não cabe, o prompt Estruturar 03 desenha as colunas e a Base Limpa é o molde.','Última coisa. Se a sua pergunta cabe numa das dez planilhas do kit, use a planilha, não invente. Se não cabe, o prompt Estruturar zero três desenha as colunas para você, e a Base Limpa é o molde. Na próxima aula, a base vira tabela dinâmica em três cliques.','Kit primeiro; a sua, quando o kit não cobre'),
 {'tipo':'fim','fala':'Resumo da aula um. Quem lê, quando, para decidir o quê. Prompt Estruturar zero um. Base limpa com as sete regras. Só então, o Excel.'},
]},
'aula-02-base-limpa-e-tabela-dinamica':{'n':2,'titulo':'Base limpa e tabela dinâmica','sub':'de 500 linhas a um resumo em 3 cliques','cenas':[
 {'tipo':'capa','fala':'Aula dois. Base limpa e tabela dinâmica: de quinhentas linhas a um resumo em três cliques. Abra a planilha dez, Base Limpa, para acompanhar.'},
 T('docs/tela-base-base.png',[0.1,0,0.72,0.55],'A aba Base tem cento e oitenta lançamentos fictícios da Prisma Comunicação: data, cliente, categoria, canal, responsável, descrição, quantidade, valor unitário. O valor total, o mês e o ano são calculados. Cliente, categoria, canal e status vêm de listas.','A Base: 180 registros, uma linha cada'),
 T('docs/tela-base-checklist.png',[0,0,0.7551,1],'Antes de analisar, o Checklist. Ele conta linhas com data sem valor, valor sem data, datas fora do intervalo, categorias e clientes fora da lista, status em branco, quantidade zero e possíveis lançamentos em dobro. A última linha diz: base pronta, pode analisar.','Rode o checklist antes de qualquer análise'),
 C('O que é uma tabela dinâmica','É um resumo da base que você monta arrastando campos: o que vai nas linhas, o que vai nas colunas, o que vai nos valores. Sem fórmula. Quando entra dado novo, você atualiza e o resumo se refaz.','Tabela dinâmica é a ferramenta mais subestimada do Excel. É um resumo da base que você monta arrastando campos, sem escrever fórmula. Categoria nas linhas, mês nas colunas, soma do valor nos valores. Entrou dado novo, atualiza e pronto.','Resumo da base sem fórmula'),
 L('No Excel: 5 passos',['Clique em qualquer célula da Base','Inserir > Tabela Dinâmica > OK (nova planilha)','Arraste Categoria para Linhas','Arraste Mês para Colunas','Arraste Valor total para Valores; Status para Filtros'],'No Excel: clique numa célula da base, menu Inserir, Tabela Dinâmica, OK. Abre uma aba nova com a lista de campos à direita. Arraste Categoria para Linhas, Mês para Colunas, Valor total para Valores. Se quiser ver só o que está pago, arraste Status para Filtros e escolha Pago.','Inserir > Tabela Dinâmica > arrastar três campos'),
 L('No Google Sheets: 4 passos',['Selecione a aba Base inteira (clique no canto)','Inserir > Tabela dinâmica > Nova página','Em Linhas, adicione Categoria; em Colunas, Mês','Em Valores, adicione Valor total (SUM)'],'No Google Sheets é parecido: selecione a base inteira, menu Inserir, Tabela dinâmica, nova página. No painel da direita, adicione Categoria em Linhas, Mês em Colunas e Valor total em Valores. Aparece o mesmo resumo.','Sheets: Inserir > Tabela dinâmica'),
 T('docs/tela-base-resumo.png',[0,0.21,0.785,0.4],'A aba Resumo da planilha faz exatamente esse resumo, mas com fórmula: SOMASES por categoria e mês, filtrando ano e status. Serve para comparar: o total da sua tabela dinâmica tem que bater com o total daqui. Se não bate, alguma linha está fora da lista.','Resumo com SOMASES: o número tem que bater'),
 T('docs/tela-base-resumo.png',[0,0.47,0.66,0.5],'Mais abaixo, o resumo por cliente: registros, valor no ano, ticket médio e último registro. Também dá para fazer na dinâmica: cliente nas linhas, contagem e soma nos valores.','Por cliente: o mesmo, de outro ângulo'),
 L('Três coisas que quebram a tabela dinâmica',['Total no meio da base: ele entra duas vezes','Célula mesclada: a dinâmica recusa ou lê errado','Data digitada como texto: o mês não agrupa'],'Três coisas quebram a dinâmica. Total no meio da base, que entra duas vezes. Célula mesclada, que ela recusa. E data digitada como texto, que não agrupa por mês. As três estão no checklist da aula um.','O que quebra: total no meio, mesclagem, data como texto'),
 C('Prompt Produzir 06','Se travar em algum menu, cole no prompt Produzir 06 o que você quer ver (linhas, colunas, valores, filtro) e a IA guia passo a passo com os nomes exatos dos menus do seu programa.','Se travar num menu, o prompt Produzir zero seis guia passo a passo com os nomes exatos dos menus, no Excel ou no Sheets. Diga o que quer nas linhas, nas colunas e nos valores.','A IA guia pelos menus, se precisar'),
 {'tipo':'fim','fala':'Resumo da aula dois. Base limpa, checklist zerado, Inserir, Tabela dinâmica, três campos arrastados. Confira o total contra o SOMASES. Na próxima aula, as oito fórmulas que resolvem oitenta por cento.'},
]},
'aula-03-as-8-formulas':{'n':3,'titulo':'As 8 fórmulas que resolvem 80%','sub':'com exemplo, o que faz e onde erra','cenas':[
 {'tipo':'capa','fala':'Aula três. As oito fórmulas que resolvem oitenta por cento do trabalho. Tenha o dicionário de fórmulas ao lado.'},
 C('1 · SOMASES','Soma uma coluna quando várias condições são verdadeiras. É a fórmula que faz todos os painéis do kit.','A primeira e mais importante: SOMASES, SUMIFS em inglês. Soma a coluna de valor quando as condições forem verdadeiras: tipo igual a despesa, e mês igual a nove. Todos os painéis do kit são feitos com ela.','SOMASES: soma com condições',box='=SOMASES(E5:E500; B5:B500; "Despesa"; I5:I500; 9)'),
 T('docs/tela-orcamento-painel.png',[0,0.17,0.63,0.27],'Olhe o painel do Orçamento. Cada célula de realizado é um SOMASES: soma o valor da aba Realizado quando a categoria é esta, o mês é o do painel e o ano é o de Config. Vinte categorias, uma fórmula copiada para baixo.','Um SOMASES por linha, copiado para baixo'),
 C('2 · CONT.SES','Conta quantas linhas atendem às condições. Quantas etapas atrasadas, quantas propostas por etapa.','A segunda é a irmã dela: CONT.SES, COUNTIFS. Em vez de somar, conta. Quantas etapas estão atrasadas. Quantas propostas estão em negociação. Mesma lógica: intervalo, condição, intervalo, condição.','CONT.SES: conta com condições',box='=CONT.SES(G5:G300; "Atrasada"; C5:C300; "Ana")'),
 C('3 · SE','Se a condição for verdadeira, devolve uma coisa; senão, outra. Aninhado, cria a coluna Situação de todas as planilhas.','A terceira: SE, IF. Se a condição for verdadeira, uma coisa; senão, outra. A coluna Situação de todas as planilhas é um SE dentro de outro: se está feito, feita; senão, se o prazo passou, atrasada; senão, se é hoje, hoje.','SE: a decisão em uma célula',box='=SE(F5="Feito"; "Feita"; SE(D5<HOJE(); "Atrasada"; SE(D5=HOJE(); "Hoje"; "No prazo")))'),
 C('4 · SEERRO','Se a fórmula der erro, mostra o que você mandar. Use para "não encontrado"; não use para esconder dado errado.','A quarta: SEERRO, IFERROR. Se a fórmula der erro, mostra o que você mandar. Serve para buscas que não acham nada. Cuidado: não use para esconder dado errado. Se o erro é a categoria fora da lista, corrija a categoria.','SEERRO: trata o erro, não esconde',box='=SEERRO(PROCV(B5; Tabela; 4; 0); "não encontrado")'),
 C('5 · ÍNDICE + CORRESP','O par que busca em qualquer direção. CORRESP acha a posição; ÍNDICE devolve o valor daquela posição em outra coluna.','A quinta é um par: ÍNDICE e CORRESP, INDEX e MATCH. CORRESP acha em que linha está o nome. ÍNDICE devolve o valor daquela linha em outra coluna. Funciona em qualquer direção, ao contrário do PROCV, e é como o kit busca o custo-hora de cada pessoa.','ÍNDICE + CORRESP: busca em qualquer direção',box='=ÍNDICE(Config!$D$11:$D$20; CORRESP(B5; Config!$A$11:$A$20; 0))'),
 C('6 · PROCV','A busca clássica: acha o valor na primeira coluna e devolve a coluna que você pedir. Simples, mas só busca para a direita.','A sexta é a clássica: PROCV, VLOOKUP. Procura o valor na primeira coluna da tabela e devolve a coluna que você pedir. É simples e todo mundo conhece; a limitação é que só busca para a direita. O zero no fim é obrigatório: busca exata.','PROCV: a busca clássica',box='=PROCV(B5; Config!$A$11:$D$20; 4; 0)'),
 C('7 · Datas: DIATRABALHOTOTAL e DATADIF','Dias úteis entre duas datas, descontando feriados; e a diferença entre datas em dias, meses ou anos.','A sétima são duas de data. DIATRABALHOTOTAL, NETWORKDAYS, conta dias úteis entre duas datas e desconta feriados de uma lista. DATADIF calcula a diferença em dias, meses ou anos. E lembre: data menos data dá o número de dias, direto.','Dias úteis e diferença entre datas',box='=DIATRABALHOTOTAL(D5; E5; Config!$H$5:$H$20)   ·   =DATADIF(A5; HOJE(); "M")'),
 C('8 · TEXTO','Transforma número ou data em texto formatado. É o que monta as frases da aba Resumo e os títulos dos painéis.','A oitava: TEXTO, TEXT. Transforma número ou data em texto com formato. É o que monta as frases da aba Resumo do Relatório Mensal e os títulos dos painéis: nome da empresa, mês, ano, tudo junto numa célula.','TEXTO: número vira frase',box='="Painel de "&TEXTO(B5; "dd/mm/yyyy")   ·   =TEXTO(E5; "R$ #.##0")'),
 L('Três hábitos que evitam 80% dos erros',['Cifrão antes de copiar: trave o que não pode mudar ($B$7). F4 alterna.','Nunca some um intervalo com total no meio.','Teste com um número que você sabe de cabeça antes de copiar para 500 linhas.'],'Três hábitos. Cifrão antes de copiar: o que não pode mudar leva cifrão, e a tecla F4 alterna. Nunca some um intervalo com total no meio. E teste com um número que você sabe de cabeça antes de copiar a fórmula para quinhentas linhas.','Cifrão, sem total no meio, teste antes de copiar'),
 C('Prompt Produzir 01','Descreva o cálculo em palavras, diga as colunas e a IA devolve a fórmula em português do Excel e em inglês do Sheets, com o cifrão no lugar e o erro possível.','Quando não souber a fórmula, o prompt Produzir zero um. Você descreve o cálculo em palavras, diz quais são as colunas, e a IA devolve a fórmula nas duas linguagens, com o cifrão no lugar. Teste em duas células antes de copiar.','A fórmula a partir de uma frase'),
 {'tipo':'fim','fala':'Resumo da aula três. SOMASES, CONT.SES, SE, SEERRO, ÍNDICE com CORRESP, PROCV, as de data e TEXTO. Oito fórmulas, oitenta por cento do trabalho. As outras cinquenta e duas estão no dicionário.'},
]},
'aula-04-o-grafico-certo':{'n':4,'titulo':'O gráfico certo para cada pergunta','sub':'evolução, comparação, composição','cenas':[
 {'tipo':'capa','fala':'Aula quatro. O gráfico certo para cada pergunta. Dois minutos, e você nunca mais usa pizza com doze fatias.'},
 C('O gráfico responde uma pergunta','Antes de escolher o tipo, escreva a pergunta. "Como a receita evoluiu?" pede um tipo; "qual categoria pesa mais?" pede outro. Gráfico sem pergunta é decoração.','Assim como a planilha, o gráfico responde uma pergunta. Escreva a pergunta primeiro. Como a receita evoluiu no ano? Qual categoria pesa mais? Previsto contra realizado? Cada pergunta tem um tipo de gráfico, e só um.','Escreva a pergunta antes de escolher o tipo'),
 L('Pergunta → gráfico',['Como evoluiu ao longo do tempo? → linha','Qual é maior entre poucas categorias? → barras (horizontais se os nomes forem longos)','Previsto contra realizado, mês a mês? → colunas lado a lado','Como se divide o total? → barras empilhadas, ou pizza só com até 5 fatias','Dois números por item (valor e %)? → tabela, não gráfico'],'A tabela de tradução. Evolução no tempo: linha. Comparação entre categorias: barras, horizontais se os nomes forem longos. Previsto contra realizado: colunas lado a lado. Divisão do total: barras empilhadas ou, no máximo, pizza com até cinco fatias. Dois números por item: tabela, não gráfico.','A tabela de tradução'),
 T('../kit-essencial/docs/tela-relatorio-painel.png',[0.01,0.75,0.64,0.25],'Evolução: o Relatório Mensal usa linha, com a meta tracejada. A pergunta é como o indicador andou no ano e se passou da meta. Um ponto por mês, uma linha, uma referência. Nada mais.','Evolução no tempo: linha com a meta'),
 T('docs/tela-orcamento-painel.png',[0.375,0.685,0.62,0.28],'Comparação de pares: o Orçamento usa colunas lado a lado, previsto e realizado por mês. Duas cores da marca, legenda embaixo, sem linha de grade pesada.','Previsto × realizado: colunas lado a lado'),
 T('docs/tela-funil-painel.png',[0,0.15,0.64,0.27],'Comparação entre etapas com nome longo: o Funil usa barras horizontais, uma por etapa. O nome cabe, o olho compara comprimento, que é o que a gente compara melhor.','Nomes longos: barras horizontais'),
 L('O título é a conclusão',['Ruim: "Receita mensal"','Bom: "Receita cresceu pelo terceiro mês e passou a meta"','Regra: quem lê só o título entende o gráfico'],'O título do gráfico é a conclusão, não o tema. Receita mensal é tema. Receita cresceu pelo terceiro mês e passou a meta é conclusão. Quem lê só o título tem que entender o gráfico. Vale para slide também.','Título: a conclusão, não o tema'),
 L('O que evitar',['3D e sombra: distorcem a leitura','Pizza com mais de 5 fatias, ou para comparar meses','Dois eixos no mesmo gráfico: ninguém sabe qual linha é qual','Mais de duas cores fora da marca','Eixo que não começa no zero em gráfico de barras'],'O que evitar. Três D e sombra. Pizza com mais de cinco fatias, ou pizza para comparar meses. Dois eixos no mesmo gráfico. Mais de duas cores. E barra com eixo que não começa no zero, que engana.','Cinco erros comuns'),
 C('Prompt Estruturar 06','Liste as suas perguntas e a IA devolve, para cada uma, o tipo de gráfico, o que vai em cada eixo e o título-conclusão. Antes de inserir qualquer gráfico.','O prompt Estruturar zero seis faz a tradução para as suas perguntas: tipo de gráfico, eixo X, eixo Y e o título. Use antes de inserir o gráfico, não depois.','A IA escolhe o tipo, você confere a pergunta'),
 {'tipo':'fim','fala':'Resumo da aula quatro. Pergunta primeiro. Linha para tempo, barra para comparação, colunas lado a lado para previsto e realizado. Título é conclusão. Sem três D, sem pizza grande.'},
]},
'aula-05-relatorio-executivo-com-ia':{'n':5,'titulo':'Relatório executivo com IA','sub':'do bloco de números ao texto revisado','cenas':[
 {'tipo':'capa','fala':'Aula cinco. Relatório executivo com IA. Do bloco de números da planilha ao texto revisado, em quarenta e cinco minutos.'},
 T('../kit-essencial/docs/tela-relatorio-painel.png',[0,0.05,0.8,0.28],'Começa no Relatório Mensal Pronto. Doze indicadores digitados, e o Painel calcula mês, mês anterior, variação, meta e situação. É daqui que saem os números. Nunca da sua memória.','Os números saem da planilha, nunca da memória'),
 T('../kit-essencial/docs/tela-relatorio-resumo.png',[0,0.15,0.62,0.45],'A aba Resumo escreve as frases-base: receita, cento e trinta e um mil e duzentos, mais cinco por cento contra agosto, meta cento e vinte mil, no alvo. E os destaques automáticos: maior alta, maior queda, mais longe da meta. Lá embaixo, o bloco único para copiar.','A aba Resumo escreve as frases-base'),
 C('Prompt Escrever 01 · relatório de 300 palavras','Cole o bloco único, diga quem lê e acrescente os seus comentários sobre o porquê dos números. A estrutura vem pronta: resultado em uma frase, destaques, pontos de atenção, próximos passos.','Copie o bloco único e cole no prompt Escrever zero um. Diga quem lê: diretoria, cliente, sócio. E acrescente os seus comentários: o que aconteceu, por quê. A estrutura já vem no prompt: resultado em uma frase, três destaques com número, pontos de atenção com causa e ação, próximos passos.','Bloco único + seus comentários = relatório',box='Escreva o relatório mensal para [diretoria], em até 300 palavras, com a estrutura: Resultado do mês em uma frase; Destaques (3, com número); Pontos de atenção (até 3, com causa e ação); Próximos passos (3, com responsável e prazo)...'),
 C('O que a IA devolve','"Setembro fechou com resultado de R$ 41.400, 11% acima de agosto e 18% acima da meta. Destaques: receita de R$ 131.200 (+5%)... Pontos de atenção: despesas de R$ 89.800, acima da meta [explicar]..."','A IA devolve o texto na estrutura pedida. Repare nos colchetes com explicar: onde ela não tinha informação, ela marca em vez de inventar. Isso está no prompt de propósito. É a sua deixa para completar com o que só você sabe.','Onde falta informação, a IA marca [explicar]'),
 C('Produzir 14 · a versão longa','Para relatório trimestral ou de mais de uma página: até 600 palavras, com "o que explica o resultado", "o que vem no próximo período" e uma decisão a tomar.','Para o relatório trimestral, ou quando uma página não basta, o prompt Produzir catorze é a versão longa: seiscentas palavras, com a seção do que explica o resultado, o que vem no próximo período e a decisão que precisa ser tomada.','Relatório longo: Produzir 14'),
 L('Revisar antes de enviar',['Cada [explicar] preenchido ou apagado','Cada número conferido na planilha, um a um','Comparações dizem com o quê (mês anterior, meta)','Sinais certos: a IA troca alta e queda','Nenhuma frase que você não saberia defender'],'Revisão. Cada explicar preenchido ou apagado. Cada número conferido na planilha, um por um; a IA troca sinal, confunde alta com queda. Toda comparação diz com o quê. E nenhuma frase que você não saberia defender numa reunião. Se não sabe defender, apaga.','Cinco conferências antes de enviar'),
 C('Produzir 17 · quando o mês foi ruim','O número e a distância da meta na primeira frase; duas causas com evidência; o que já foi feito; o que será feito, com prazo; o que você precisa de quem lê. Sem drama, sem culpar.','Quando o mês foi ruim, o prompt Produzir dezessete. O número e a distância da meta na primeira frase, duas causas com evidência, o que já foi feito, o que será feito, o que você precisa de quem lê. Sem drama e sem culpar ninguém. Resultado ruim bem comunicado dá mais credibilidade que resultado bom escondido.','Resultado ruim: Produzir 17'),
 T('docs/tela-ata-resumo.png',[0,0.06,0.8,0.38],'Outro bloco pronto para a IA está na planilha Ata e Pendências: a aba Resumo monta a reunião escolhida, decisões e pendências, em um bloco. Com o prompt Escrever zero sete vira o resumo para quem não foi; com o Escrever zero dois, o e-mail de cobrança.','Ata e Pendências também gera bloco para a IA'),
 {'tipo':'fim','fala':'Resumo da aula cinco. Planilha entrega os números. Bloco único no prompt, com os seus comentários. IA entrega as palavras. Você revisa cada número e cada explicar. Na próxima aula, o mesmo bloco vira apresentação.'},
]},
'aula-06-apresentacao-de-8-slides-com-ia':{'n':6,'titulo':'Apresentação de 8 slides com IA','sub':'roteiro, modelo, sem enfeite','cenas':[
 {'tipo':'capa','fala':'Aula seis. Apresentação de oito slides com IA. O mesmo bloco de números da aula cinco vira o roteiro; o modelo do kit vira os slides.'},
 C('Prompt Apresentar 01 · roteiro de 8 slides','Cole o bloco único da aba Resumo. A IA devolve, slide a slide: título-conclusão, o número ou gráfico que entra e a fala em duas frases.','Cole o bloco único da aba Resumo no prompt Apresentar zero um. A IA devolve o roteiro slide a slide: o título, que é a conclusão, o número ou gráfico que entra e a fala em duas frases. Você ainda não abriu o PowerPoint.','Roteiro antes do PowerPoint',box='Monte o roteiro de 8 slides para [público]: para cada slide, título (que é a conclusão), o número ou gráfico, a fala em 2 frases...'),
 T('docs/slides-grid.png',[0,0,1,0.5],'O modelo de oito slides do kit. Capa com a frase do mês. Resumo em três números. Dois destaques positivos, um com gráfico e um com número grande. Dois pontos de atenção, sempre com ação. Próximos passos com responsável. E as decisões pedidas. Você troca os textos e os números; a estrutura fica.','O modelo de 8 slides: troque o texto, mantenha a estrutura'),
 T('docs/slide-2.png',[0,0,1,1],'Slide dois, o resumo. Três números grandes, o mais importante em amarelo. Uma frase embaixo dizendo quantos indicadores estão no alvo. Quem só vê este slide já sabe como foi o mês.','Resumo: três números, o principal em destaque'),
 T('docs/slide-3.png',[0,0,1,1],'Slide de destaque com gráfico. Título é a conclusão: receita cresceu pelo terceiro mês e passou a meta. Gráfico à esquerda, com a linha da meta. À direita, três frases: o que puxou. Para trocar os números, clique no gráfico e edite os dados.','Destaque: gráfico à esquerda, três frases à direita'),
 T('docs/slide-7.png',[0,0,1,1],'Slide de próximos passos. Cada ação com responsável e data. A regra da apresentação inteira está aqui: sem responsável, não é ação, é desejo.','Próximos passos: responsável e data'),
 L('Cinco regras do slide que funciona',['Título é a conclusão, não o tema','Um gráfico por slide, com título e unidade','O primeiro slide de conteúdo já dá o resultado','Nada com letra menor que 18','O último slide pede uma decisão'],'Cinco regras. Título é conclusão. Um gráfico por slide, com unidade. O primeiro slide de conteúdo já diz o resultado, ninguém espera até o fim. Nada com letra menor que dezoito. E o último slide pede uma decisão, não agradece.','Cinco regras'),
 T('docs/trimestre-grid.jpg',[0,0,1,0.5],'Para o fim do trimestre, o modelo de doze slides: três números, progresso por objetivo, um slide por objetivo, financeiro, comercial, riscos, metas do próximo trimestre e decisões. Alimentado pelas planilhas Metas, Orçamento e Funil.','O modelo de 12 slides do trimestre'),
 C('Prompt Produzir 20 · as perguntas difíceis','Cole o roteiro e os números. A IA lista as oito perguntas mais prováveis da diretoria, com a resposta curta e o número que a sustenta. Marca as que os seus números não respondem.','Antes de apresentar, o prompt Produzir vinte. Ele faz o papel do diretor cético: lista as oito perguntas mais prováveis, com a resposta curta e o número que sustenta. E marca as perguntas que os seus números não conseguem responder. Prepare essas antes da reunião.','Ensaie as perguntas antes da reunião'),
 {'tipo':'fim','fala':'Resumo da aula seis. Roteiro com o Apresentar zero um. Modelo do kit, troque o texto. Cinco regras. Perguntas difíceis com o Produzir vinte. Na próxima aula, a revisão final antes de enviar.'},
]},
'aula-07-revisar-antes-de-enviar':{'n':7,'titulo':'Revisar antes de enviar','sub':'os erros que a IA comete e como pegar','cenas':[
 {'tipo':'capa','fala':'Aula sete. Revisar antes de enviar. Os erros que a IA comete com mais frequência e os dois minutos que evitam o e-mail de correção.'},
 L('Os cinco erros mais comuns da IA',['Inventa um número que não estava no bloco','Troca o sinal: alta vira queda','Confunde mês anterior com meta','Escreve com confiança o que marcou como [explicar]','Generaliza: "todos os indicadores melhoraram"'],'A IA erra de cinco jeitos previsíveis. Inventa um número que não estava no bloco. Troca o sinal, alta vira queda. Confunde mês anterior com meta. Escreve com confiança o que devia estar entre colchetes. E generaliza: todos os indicadores melhoraram, quando foram dez de doze. Sabendo os cinco, você pega em dois minutos.','Cinco erros previsíveis'),
 C('A regra: cada número, um dedo na planilha','Leia o texto com a planilha aberta ao lado. A cada número, aponte a célula de onde ele veio. Número sem célula é número inventado.','A regra mais simples e mais eficaz: leia o texto com a planilha aberta do lado. Cada número que aparecer no texto, aponte a célula de onde ele veio. Se não tem célula, é invenção. Apaga ou corrige.','Número sem célula é invenção'),
 T('docs/tela-base-checklist.png',[0,0,0.7551,1],'A revisão da planilha está automatizada na Base Limpa: o checklist conta os problemas. Para as outras planilhas, o checklist de revisão do kit tem nove itens: totais batem, fórmula igual do topo ao fim, sem total no meio, datas são datas, categorias de lista.','Planilha: o checklist conta os problemas'),
 L('Checklist do relatório',['Primeira frase diz o principal','Todo [explicar] preenchido ou apagado','Cada número conferido, um a um','Comparações dizem com o quê','Nenhuma frase que eu não saberia defender','Li em voz alta uma vez'],'Checklist do relatório. Primeira frase diz o principal. Todo explicar resolvido. Cada número conferido. Comparações dizem com o quê. Nenhuma frase que eu não saberia defender. E leitura em voz alta uma vez: frase que embola na boca, embola na cabeça de quem lê.','Relatório: seis conferências'),
 C('Prompt Revisar 03 · consistência entre planilha e texto','Cole a tabela e o texto. A IA compara número por número e lista as divergências. Ela revisa; você decide.','Para acelerar, o prompt Revisar zero três: cole a tabela e o texto, e a IA compara número por número, listando as divergências. Ela ajuda a revisar, mas a decisão final continua sendo sua: a IA também erra ao revisar.','A IA ajuda a revisar; você decide'),
 L('Checklist da apresentação',['Título de cada slide é uma conclusão','Um gráfico por slide, letra maior que 18','Tem slide de pontos de atenção','O último slide pede uma decisão','Cronometrei: cabe em 80% do tempo'],'Checklist da apresentação. Títulos são conclusões. Um gráfico por slide, letra maior que dezoito. Tem slide de pontos de atenção. O último pede decisão. E cronometrei: cabe em oitenta por cento do tempo da reunião, porque sempre atrasa.','Apresentação: cinco conferências'),
 L('Checklist do envio',['Destinatários, assunto e anexo certos; abri o anexo','A versão do cliente não tem número interno','Nome do arquivo faz sentido daqui a 6 meses'],'E o envio. Destinatários, assunto e anexo certos, e o anexo aberto antes de enviar. A versão do cliente sem número interno: custo, margem, salário. E o nome do arquivo que faça sentido daqui a seis meses: cliente, assunto, ano e mês.','Envio: três conferências'),
 {'tipo':'fim','fala':'Resumo da aula sete. Cinco erros previsíveis. Cada número, um dedo na planilha. Os quatro checklists estão no PDF do kit: planilha, relatório, apresentação e envio. Dois minutos cada.'},
]},
'aula-08-a-rotina':{'n':8,'titulo':'A rotina: segunda, sexta, dia 30','sub':'as 10 planilhas no seu calendário','cenas':[
 {'tipo':'capa','fala':'Aula oito, a última. A rotina. Em que dia da semana e do mês cada planilha entra, para o método funcionar sem esforço.'},
 C('O método só funciona com rotina','Planilha que não tem dia marcado não é preenchida. A rotina do kit cabe em: 10 minutos na segunda, 15 na sexta, 2 horas no fechamento do mês e meia tarde no fim do trimestre.','Nenhuma planilha funciona sem dia marcado. A rotina do kit é curta: dez minutos na segunda, quinze na sexta, duas horas no fechamento do mês e meia tarde no fim do trimestre. Vamos passar por cada uma.','Dia marcado ou não acontece'),
 L('Segunda-feira, 10 minutos',['Semana Organizada: atualizar tarefas, olhar a aba Hoje','Projetos e Prazos: atualizar o % das etapas em andamento','Ata e Pendências: o que cobrar primeiro'],'Segunda-feira, dez minutos. Semana Organizada: atualiza as tarefas, olha a aba Hoje. Projetos e Prazos: atualiza o percentual das etapas em andamento. Ata e Pendências: vê o que cobrar primeiro.','Segunda: tarefas, etapas, pendências'),
 T('docs/tela-projetos-painel.png',[0,0.45,0.75,0.32],'O painel de Projetos na segunda: projetos com atraso em vermelho, a lista do que fazer primeiro já ordenada. Se uma etapa estourou, é aqui que você vê antes do cliente.','Projetos: o que atrasou, antes do cliente perguntar'),
 T('docs/tela-ata-aberto.png',[0,0.277,0.81,0.345],'Ata e Pendências na segunda: as atrasadas em vermelho, as de hoje em amarelo. Copie a lista, use o prompt Escrever dez e mande a cobrança educada. Cinco minutos.','Pendências: cobrar com o Escrever 10'),
 L('Sexta-feira, 15 minutos',['Metas do Trimestre: valor atual de cada resultado-chave, coluna da semana','Funil de Propostas: etapas e datas; cobrar as paradas','Horas e Custo: conferir se todos lançaram'],'Sexta-feira, quinze minutos. Metas do Trimestre: atualiza o valor atual e copia para a coluna da semana. Funil: atualiza etapas e datas, cobra as propostas paradas. Horas: confere se todo mundo lançou.','Sexta: metas, funil, horas'),
 T('docs/tela-metas-painel.png',[0,0.45,0.88,0.44],'Metas na sexta: o semáforo mostra o que está no ritmo e o que está em risco, comparando o progresso com o tempo já decorrido. Em risco na sexta é conversa na segunda, não no fim do trimestre.','Metas: em risco na sexta, conversa na segunda'),
 T('docs/tela-funil-painel.png',[0,0.415,0.64,0.3],'Funil na sexta: o que mexer primeiro, com as propostas vencidas e paradas, maior valor no topo. Uma mensagem por proposta, com o prompt Escrever zero dois.','Funil: as paradas, maior valor primeiro'),
 L('Dia 30 (ou dia 5), 2 horas',['Ganhos e Gastos ou Orçamento: fechar o mês','Relatório Mensal Pronto: os 12 números, aba Resumo','Prompt Escrever 01 ou Produzir 14 → relatório','Modelo de 8 slides → apresentação','Checklist → enviar'],'Dia trinta, ou dia cinco, duas horas. Ganhos e Gastos ou Orçamento: fecha o mês. Relatório Mensal: os doze números, aba Resumo. Prompt Escrever zero um: o relatório. Modelo de oito slides: a apresentação. Checklist: envia. É a sequência das aulas cinco, seis e sete.','Fechamento do mês em cinco passos'),
 T('docs/tela-orcamento-painel.png',[0,0.17,0.63,0.27],'O Orçamento no fechamento: o que estourou em vermelho, o desvio em reais e por cento. É o número que entra no relatório e, se for o caso, no prompt Produzir dezessete, do resultado ruim.','Orçamento: o que estourou entra no relatório'),
 L('Fim do trimestre, meia tarde',['Metas: fechar o trimestre e definir as próximas','Orçamento: acumulado do ano','Funil: conversão por origem e motivos de perda','Modelo de 12 slides → resultado do trimestre','Produzir 20 → as perguntas difíceis'],'Fim do trimestre, meia tarde. Metas: fecha e define as próximas. Orçamento: acumulado do ano. Funil: conversão por origem e por que você perde. Modelo de doze slides. E o Produzir vinte, para chegar na reunião com as perguntas difíceis já respondidas.','Trimestre: metas, acumulado, funil, 12 slides'),
 C('Prompt Produzir 28 · o seu fechamento','Diga quais planilhas você usa, quem recebe e o dia. A IA monta o checklist do seu fechamento mensal, com tempo por passo e o prompt de cada etapa. Cronometre uma vez e cole na aba Como usar.','Para adaptar tudo isso ao seu caso, o prompt Produzir vinte e oito monta o checklist do seu fechamento: quais planilhas, quem recebe, que dia. Rode uma vez cronometrando e cole o resultado na aba Como usar do Relatório Mensal.','A rotina no seu caso: Produzir 28'),
 {'tipo':'fim','fala':'Fim do curso. Estruturar, preencher, perguntar, entregar. Dez planilhas, oitenta prompts, uma rotina. Dúvida sobre os arquivos: suporte por e-mail. O resto é fazer na segunda que vem.'},
]},
}
